import { exhibitionForms } from '../utils/exhibitionForms.js';

const sourcesByForm = {
  photographs: 'about:gallery',
  'light-table': 'about:gallery',
  'photo-carousel': 'about:gallery',
  'photo-ribbon': 'about:gallery',
  'photo-viewer': 'about:gallery',
  folio: 'fragments:first-camera-another-way-of-seeing',
  'reading-case': 'fragments:the-projection-of-thought',
  'hanging-scroll': 'fragments:music-that-became-more-spacious',
  'reading-roll': 'fragments:rich-traces-and-open-paths',
  screen: 'early:batch-downloading-scientific-american-episodes',
  globe: 'interactive.travels.globe',
  'interactive-console': 'interactive.insurance.rule-engine',
  'interactive-table': 'interactive.rag.flowchart-reconstruction',
  'interactive-display': 'interactive.it-ops.knowledge',
};

export function createExhibitionShowroom(catalog) {
  const sources = new Map(catalog.map(source => [source.source_id, source]));
  const forms = {};
  const blocks = exhibitionForms.map((form, index) => {
    const id = sourcesByForm[form.id];
    const source = sources.get(id);
    if (!source) throw new Error(`Missing showroom work ${id}`);
    forms[`0-${index}`] = form.id;
    return { kind: 'source', source_id: id, presentation: source.presentations[0] };
  });
  return {
    sources, forms,
    view: {
      title: 'The exhibition study room',
      illustration: { src: '/assets/exhibition-study-room.webp' },
      question: 'How can a work take its place in an exhibition?',
      dek: 'Fourteen ways to spend time with a work. Turn a photograph, unfold a screen, read a continuous page or try an interactive project. Every form is here in one room. Open the visit guide to jump to any of them.',
      sections: [{
        heading: 'An open collection of forms',
        exhibition_intro: 'Walk between the works or choose a form in the visit guide. The five photographic displays share Henry’s collection so you can compare their proportions and movement. Each reading surface carries a complete fragment, and the interactive displays open the original working components.',
        blocks,
      }],
    },
  };
}
