<template>
  <main class="exhibition-showroom-page">
    <ViewExhibition v-if="room" :view="room.view" :sources="room.sources" :current-sources="room.sources" :exhibit-forms="room.forms" :initial-position="initialPosition" showroom showcase-linked @close="leave" />
    <div v-else class="showroom-opening" role="status">
      <p>{{ error ? 'The study room could not open.' : 'Opening the exhibition study room' }}</p>
      <button v-if="error" type="button" @click="load">Try again</button>
      <router-link v-if="error" to="/views">Return to Views</router-link>
    </div>
  </main>
</template>

<script>
import ViewExhibition from './view/ViewExhibition.vue';
import { createViewCatalog } from '../utils/viewCatalog.js';
import { createExhibitionShowroom } from '../data/exhibitionShowroom.js';
import { exhibitionForms } from '../utils/exhibitionForms.js';
import { revealViewTransition } from '../utils/viewPresentationTransition';

export default {
  name: 'ExhibitionShowroomPage',
  components: { ViewExhibition },
  data: () => ({ room: null, error: false }),
  computed: {
    initialPosition() {
      const index = exhibitionForms.findIndex(form => form.id === this.$route.query.form);
      return index < 0 ? null : { sectionIndex: 0, blockIndex: index };
    },
  },
  mounted() { this.load(); },
  methods: {
    async load() {
      this.error = false;
      try {
        const response = await fetch('/assets/view-index.json');
        if (!response.ok) throw new Error('The collection is unavailable');
        this.room = createExhibitionShowroom(createViewCatalog(await response.json()));
      } catch { this.error = true; revealViewTransition(); }
    },
    leave(position, navigation = {}) {
      this.$router.push(navigation.target === 'site' ? navigation.path : '/views').then(revealViewTransition);
    },
  },
};
</script>

<style scoped>
.exhibition-showroom-page { min-height: 100dvh; background: var(--site-bg-primary, #f5f3ee); }
.showroom-opening { display: grid; place-content: center; gap: 20px; min-height: 80dvh; padding: 24px; text-align: center; color: var(--site-text-primary, #36332f); }
.showroom-opening button { justify-self: center; padding: 10px 20px; border: 1px solid currentColor; border-radius: 4px; background: transparent; color: inherit; font: inherit; cursor: pointer; }
.showroom-opening a { color: inherit; }
</style>
